def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    Overlay values replace base values. If both values for a key are dicts,
    they are merged recursively. Lists, None, and scalars from the overlay
    replace the base value wholesale. A None in the overlay does not delete
    the key — it sets it to None. The result is deep-independent of both
    inputs (no shared nested references).
    """
    result = {}

    for key, base_val in base.items():
        if key in overlay:
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = _clone(overlay_val)
        else:
            result[key] = _clone(base_val)

    for key, overlay_val in overlay.items():
        if key not in base:
            result[key] = _clone(overlay_val)

    return result


def _clone(value):
    """Return a deep copy of a JSON-like value."""
    if isinstance(value, dict):
        return {k: _clone(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_clone(item) for item in value]
    # str, int, float, bool, None are immutable — safe to return as-is
    return value
```

