def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for root; never a trailing slash elsewhere.

    Raises ValueError if the path is not absolute (does not start with '/').
    """
    if not path.startswith("/"):
        raise ValueError(f"not an absolute path: {path!r}")

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # else: at root, ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

