def redact(value, sensitive):
    sensitive_lower = frozenset(s.lower() for s in sensitive)

    def _redact(v):
        if isinstance(v, dict):
            return {
                k: "[REDACTED]" if k.lower() in sensitive_lower else _redact(val)
                for k, val in v.items()
            }
        if isinstance(v, list):
            return [_redact(item) for item in v]
        return v

    return _redact(value)
```

